<?php
require __DIR__ . '/includes/bootstrap.php'; require_login(); no_cache();
$pageTitle='Community comments';$error='';
if(request_is_post()){
 if(!verify_csrf())$error='Your form session expired. Refresh and try again.';
 else{$text=is_string($_POST['comment']??null)?trim($_POST['comment']):'';$error=validate_field('comment',$text)??'';if(!$error){$db=db_or_error();if(!$db)$error='Comments are unavailable because the database could not be reached.';else{try{$q=$db->prepare('INSERT INTO comments (user_id,comment_text) VALUES (:user_id,:comment_text)');$q->execute(['user_id'=>current_user()['id'],'comment_text'=>$text]);flash('success','Your comment was posted.');redirect('comments.php');}catch(Throwable $e){error_log('Comment save failed: '.$e->getMessage());$error='Your comment could not be saved. Please try again.';}}}}
}
$db=db_or_error();$comments=[];if($db)$comments=$db->query('SELECT c.comment_text,c.created_at,u.username FROM comments c JOIN users u ON u.id=c.user_id ORDER BY c.created_at DESC LIMIT 100')->fetchAll();
require __DIR__.'/includes/header.php';
?>
<main class="container page-space"><div class="page-intro"><span class="eyebrow">COMMUNITY NOTES</span><h1>A thoughtful <span class="accent">conversation.</span></h1><p class="lead">Share a short, respectful note about staying informed. Comments are visible to signed-in members.</p></div><div class="comments-layout"><section class="form-card comment-form"><div class="form-heading"><span class="eyebrow">WRITE A COMMENT</span><h2>What would you like to share?</h2></div><?php if($error):?><div class="alert error" role="alert"><?=h($error)?></div><?php endif;?><form method="post" data-validate="comment"><?=csrf_field()?><label class="field"><span>Comment <small class="muted">(up to 500 characters)</small></span><textarea name="comment" required maxlength="500" rows="5" placeholder="Keep it kind and useful…" aria-describedby="comment-hint"></textarea><small id="comment-hint" class="field-hint">HTML tags are not accepted. Your text will display safely.</small><small class="field-error"></small></label><button class="button primary" type="submit">Post comment <span aria-hidden="true">→</span></button></form></section><section class="comment-list"><div class="list-heading"><div><span class="eyebrow">COMMUNITY</span><h2>Recent comments</h2></div><span class="count-badge"><?=count($comments)?> shown</span></div><?php if(!$db):?><div class="alert error">Comments are temporarily unavailable. Check the database connection.</div><?php elseif(!$comments):?><div class="empty-state"><span>⌁</span><h3>No comments yet</h3><p>Be the first to add a helpful note.</p></div><?php else:?><?php foreach($comments as $comment):?><article class="comment-item"><div class="comment-avatar"><?=h(strtoupper(substr($comment['username'],0,1)))?></div><div><div class="comment-meta"><strong><?=h($comment['username'])?></strong><time><?=h($comment['created_at'])?></time></div><p><?=nl2br(h($comment['comment_text']))?></p></div></article><?php endforeach;?><?php endif;?></section></div></main>
<?php require __DIR__.'/includes/footer.php'; ?>
